func (e *executableSchema) Exec(ctx context.Context) graphql.ResponseHandler {
	opCtx := graphql.GetOperationContext(ctx)
	ec := executionContext{opCtx, e, 0, 0, make(chan graphql.DeferredResult)}
	inputUnmarshalMap := graphql.BuildUnmarshalerMap(
		ec.unmarshalInputAdvantageHeadersInput,
		ec.unmarshalInputAllergyInput,
		ec.unmarshalInputAttachmentInput,
		ec.unmarshalInputBusinessHoursInput,
		ec.unmarshalInputCodingInput,
		ec.unmarshalInputCompositionInput,
		ec.unmarshalInputConditionInput,
		ec.unmarshalInputConsentInput,
		ec.unmarshalInputContactInput,
		ec.unmarshalInputCoordinatesInput,
		ec.unmarshalInputCreateReferralInput,
		ec.unmarshalInputDiagnosticReportInput,
		ec.unmarshalInputDosageInstructionInput,
		ec.unmarshalInputEncounterInput,
		ec.unmarshalInputEpisodeOfCareInput,
		ec.unmarshalInputFacilityIdentifierInput,
		ec.unmarshalInputFacilityInput,
		ec.unmarshalInputFacilityServiceInput,
		ec.unmarshalInputFilterInput,
		ec.unmarshalInputHealthTimelineInput,
		ec.unmarshalInputIdentifierInput,
		ec.unmarshalInputMediaInput,
		ec.unmarshalInputMedicationRequestFilterInput,
		ec.unmarshalInputMetaInput,
		ec.unmarshalInputObservationInput,
		ec.unmarshalInputPSAInput,
		ec.unmarshalInputPagination,
		ec.unmarshalInputPaginationInput,
		ec.unmarshalInputPatchCompositionInput,
		ec.unmarshalInputPatchPatientInput,
		ec.unmarshalInputPatchTaskInput,
		ec.unmarshalInputPatientInput,
		ec.unmarshalInputPrescriptionInput,
		ec.unmarshalInputPrescriptionMedicationInput,
		ec.unmarshalInputQuantityInput,
		ec.unmarshalInputQuestionnaireResponseInput,
		ec.unmarshalInputQuestionnaireResponseItemAnswerInput,
		ec.unmarshalInputQuestionnaireResponseItemInput,
		ec.unmarshalInputReactionInput,
		ec.unmarshalInputReferenceInput,
		ec.unmarshalInputReferralFacility,
		ec.unmarshalInputReferralInput,
		ec.unmarshalInputRiskAssessmentFilterInput,
		ec.unmarshalInputScheduleAppointmentInput,
		ec.unmarshalInputSectionInput,
		ec.unmarshalInputServiceIdentifierInput,
		ec.unmarshalInputServiceRequestFilterInput,
		ec.unmarshalInputTaskFilterInput,
		ec.unmarshalInputTaskInput,
		ec.unmarshalInputTestOrder,
		ec.unmarshalInputTestOrderObservation,
		ec.unmarshalInputTestOrderResult,
		ec.unmarshalInputTestResultInput,
		ec.unmarshalInputValueSetDataInput,
	)
	first := true

	switch opCtx.Operation.Operation {
	case ast.Query:
		return func(ctx context.Context) *graphql.Response {
			var response graphql.Response
			var data graphql.Marshaler
			if first {
				first = false
				ctx = graphql.WithUnmarshalerMap(ctx, inputUnmarshalMap)
				data = ec._Query(ctx, opCtx.Operation.SelectionSet)
			} else {
				if atomic.LoadInt32(&ec.pendingDeferred) > 0 {
					result := <-ec.deferredResults
					atomic.AddInt32(&ec.pendingDeferred, -1)
					data = result.Result
					response.Path = result.Path
					response.Label = result.Label
					response.Errors = result.Errors
				} else {
					return nil
				}
			}
			var buf bytes.Buffer
			data.MarshalGQL(&buf)
			response.Data = buf.Bytes()
			if atomic.LoadInt32(&ec.deferred) > 0 {
				hasNext := atomic.LoadInt32(&ec.pendingDeferred) > 0
				response.HasNext = &hasNext
			}

			return &response
		}
	case ast.Mutation:
		return func(ctx context.Context) *graphql.Response {
			if !first {
				return nil
			}
			first = false
			ctx = graphql.WithUnmarshalerMap(ctx, inputUnmarshalMap)
			data := ec._Mutation(ctx, opCtx.Operation.SelectionSet)
			var buf bytes.Buffer
			data.MarshalGQL(&buf)

			return &graphql.Response{
				Data: buf.Bytes(),
			}
		}

	default:
		return graphql.OneShot(graphql.ErrorResponse(ctx, "unsupported GraphQL operation"))
	}
}

type executionContext struct {
	*graphql.OperationContext
	*executableSchema
	deferred        int32
	pendingDeferred int32
	deferredResults chan graphql.DeferredResult
}

func (ec *executionContext) processDeferredGroup(dg graphql.DeferredGroup) {
	atomic.AddInt32(&ec.pendingDeferred, 1)
	go func() {
		ctx := graphql.WithFreshResponseContext(dg.Context)
		dg.FieldSet.Dispatch(ctx)
		ds := graphql.DeferredResult{
			Path:   dg.Path,
			Label:  dg.Label,
			Result: dg.FieldSet,
			Errors: graphql.GetErrors(ctx),
		}
		// null fields should bubble up
		if dg.FieldSet.Invalids > 0 {
			ds.Result = graphql.Null
		}
		ec.deferredResults <- ds
	}()
}

func (ec *executionContext) introspectSchema() (*introspection.Schema, error) {
	if ec.DisableIntrospection {
		return nil, errors.New("introspection disabled")
	}
	return introspection.WrapSchema(ec.Schema()), nil
}

func (ec *executionContext) introspectType(name string) (*introspection.Type, error) {
	if ec.DisableIntrospection {
		return nil, errors.New("introspection disabled")
	}
	return introspection.WrapTypeFromDef(ec.Schema(), ec.Schema().Types[name]), nil
}

